solutions.naive:
class Solution:
    def countPrimes(self, n: int) -> int:
        count = 0
        for x in range(2, n):
            prime = True
            for d in range(2, x):
                if x % d == 0:
                    prime = False
                    break
            if prime:
                count += 1
        return count

solutions.better:
class Solution:
    def countPrimes(self, n: int) -> int:
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True

        return sum(1 for x in range(2, n) if is_prime(x))

solutions.optimal:
class Solution:
    def countPrimes(self, n: int) -> int:
        if n <= 2:
            return 0
        is_prime = [True] * n
        is_prime[0] = is_prime[1] = False
        p = 2
        while p * p < n:
            if is_prime[p]:
                # Smaller multiples were already marked by smaller primes.
                for multiple in range(p * p, n, p):
                    is_prime[multiple] = False
            p += 1
        return sum(is_prime)

